-- Sweden deep-dive page translations: page fields, stats, cards, steps, portal.
-- No penalty rows (no mandate exists yet, so nothing to enforce).

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Totalmente descentralizado — sin mandato B2B nacional', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La cuestión del mandato nacional B2B de Suecia sigue genuinamente abierta a la espera de la investigación nacional prevista para noviembre de 2027 — confirme los últimos avances directamente con DIGG o Skatteverket antes de tomar decisiones de cumplimiento a largo plazo.', 'Suecia tiene uno de los historiales de facturación electrónica más largos de Europa en el sector público — y una de sus preguntas más abiertas sobre si eso alguna vez se extenderá a la empresa privada.', 'Suecia nunca ha operado un único esquema nacional obligatorio como sí hacen Noruega (EHF) o Dinamarca (OIOUBL) — fue directamente al estándar europeo.', 'No existe realmente ninguna plataforma central sueca — este es uno de los modelos más puramente descentralizados de este seguimiento. Suecia no tiene un mandato nacional B2B legislado. Lo genuinamente nuevo: una investigación nacional sobre la implementación del ViDA lanzada el 5 de febrero de 2026, encargada explícitamente de evaluar si se debe imponer la facturación electrónica B2B/G2B nacional, con conclusiones previstas a más tardar el 30 de noviembre de 2027.', 'Sin un mandato nacional B2B, "prepararse" aquí significa posicionarse con sensatez en lugar de cumplir un plazo estricto.', 'No existe un régimen de sanciones para el B2B porque todavía no existe ningún mandato — la verdadera historia aquí es lo que podría producir la investigación de 2026.' FROM countries WHERE name_en = 'Sweden';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Vollständig dezentral — keine inländische B2B-Pflicht', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Frage der inländischen B2B-Pflicht Schwedens bleibt bis zur nationalen Untersuchung, die im November 2027 fällig ist, wirklich offen — bestätigen Sie aktuelle Entwicklungen direkt bei DIGG oder Skatteverket, bevor Sie langfristige Compliance-Entscheidungen treffen.', 'Schweden hat eine der längsten Erfolgsbilanzen der E-Rechnung im öffentlichen Sektor in Europa — und eine seiner offeneren Fragen dazu, ob sich das jemals auf die Privatwirtschaft ausweitet.', 'Schweden hat nie ein einziges verpflichtendes nationales Schema betrieben, wie es Norwegen (EHF) oder Dänemark (OIOUBL) tun — es ging direkt zum europäischen Standard über.', 'Es gibt wirklich keine zentrale schwedische Plattform — dies ist eines der am reinsten dezentralen Modelle in diesem Tracker. Schweden hat keine gesetzlich verankerte inländische B2B-Pflicht. Was wirklich neu ist: eine am 5. Februar 2026 gestartete nationale Untersuchung zur ViDA-Umsetzung, ausdrücklich beauftragt zu bewerten, ob eine inländische B2B-/G2B-E-Rechnungspflicht eingeführt werden soll, mit Ergebnissen, die spätestens am 30. November 2027 fällig sind.', 'Ohne inländische B2B-Pflicht bedeutet "sich vorbereiten" hier, sich sinnvoll zu positionieren, statt eine feste Frist einzuhalten.', 'Für B2B besteht kein Bußgeldregime, weil noch keine Pflicht existiert — die eigentliche Geschichte hier ist, was die Untersuchung von 2026 hervorbringen könnte.' FROM countries WHERE name_en = 'Sweden';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Entièrement décentralisé — aucune obligation B2B nationale', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La question de l''obligation B2B nationale de la Suède reste véritablement ouverte dans l''attente de l''enquête nationale prévue pour novembre 2027 — confirmez les évolutions actuelles directement auprès de DIGG ou de Skatteverket avant de prendre des décisions de conformité à long terme.', 'La Suède possède l''un des plus longs historiques de facturation électronique d''Europe dans le secteur public — et l''une de ses questions les plus ouvertes quant à savoir si cela s''étendra un jour aux entreprises privées.', 'La Suède n''a jamais exploité un schéma national unique obligatoire comme le font la Norvège (EHF) ou le Danemark (OIOUBL) — elle est passée directement à la norme européenne.', 'Il n''existe véritablement aucune plateforme centrale suédoise — c''est l''un des modèles les plus purement décentralisés de ce suivi. La Suède n''a pas d''obligation B2B nationale légiférée. Ce qui est véritablement nouveau : une enquête nationale sur la mise en œuvre de ViDA lancée le 5 février 2026, explicitement chargée d''évaluer s''il convient de rendre obligatoire la facturation électronique B2B/G2B nationale, avec des conclusions attendues au plus tard le 30 novembre 2027.', 'En l''absence d''obligation B2B nationale, « se préparer » signifie ici se positionner intelligemment plutôt que respecter une échéance stricte.', 'Aucun régime de sanctions n''existe pour le B2B car aucune obligation n''existe encore — l''enjeu réel ici est ce que l''enquête de 2026 pourrait produire.' FROM countries WHERE name_en = 'Sweden';

