INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formatos actuales', '[["Preferido", "Peppol BIS Billing 3.0 (UBL, EN 16931)"], ["Heredado, aún aceptado", "Svefaktura 1.0 / 2.0"], ["Heredado, en fase de eliminación", "SFTI ESAP 6 Fulltextfaktura, EDIFACT"]]', 'Muchas empresas suecas todavía usan Svefaktura para el comercio B2B — si está integrándose con socios suecos, esté preparado para admitir tanto Peppol BIS como los formatos nacionales más antiguos durante un tiempo más.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Aktuelle Formate', '[["Bevorzugt", "Peppol BIS Billing 3.0 (UBL, EN 16931)"], ["Veraltet, noch akzeptiert", "Svefaktura 1.0 / 2.0"], ["Veraltet, wird ausgemustert", "SFTI ESAP 6 Fulltextfaktura, EDIFACT"]]', 'Viele schwedische Unternehmen nutzen für den B2B-Handel weiterhin Svefaktura — wenn Sie mit schwedischen Partnern integrieren, seien Sie bereit, noch eine Weile sowohl Peppol BIS als auch die älteren nationalen Formate zu unterstützen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Formats actuels', '[["Privilégié", "Peppol BIS Billing 3.0 (UBL, EN 16931)"], ["Hérité, encore accepté", "Svefaktura 1.0 / 2.0"], ["Hérité, en cours d''abandon", "SFTI ESAP 6 Fulltextfaktura, EDIFACT"]]', 'De nombreuses entreprises suédoises utilisent encore Svefaktura pour le commerce B2B — si vous vous intégrez avec des partenaires suédois, soyez prêt à prendre en charge à la fois Peppol BIS et les anciens formats nationaux encore un moment.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Firma y archivo', '[["Firma digital", "No requerida"], ["Período de conservación", "7 años"]]', 'No se aplica ningún requisito de firma electrónica ni a las facturas del sector público ni a las del sector privado — un requisito genuinamente más ligero que el XAdES/CAdES obligatorio de Italia.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Signatur & Archivierung', '[["Digitale Signatur", "Nicht erforderlich"], ["Aufbewahrungsfrist", "7 Jahre"]]', 'Weder für Rechnungen des öffentlichen noch des privaten Sektors gilt eine Pflicht zur elektronischen Signatur — eine wirklich leichtere Anforderung als Italiens verpflichtendes XAdES/CAdES.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Signature et archivage', '[["Signature numérique", "Non requise"], ["Durée de conservation", "7 ans"]]', 'Aucune exigence de signature électronique ne s''applique aux factures du secteur public ou privé — une exigence véritablement plus légère que le XAdES/CAdES obligatoire en Italie.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin CIUS nacional más allá de Peppol BIS', '[["Extensiones nacionales", "Ninguna más allá del propio CIUS de Peppol BIS Billing"]]', 'A diferencia del HR-FISK de Croacia o el RO_CIUS de Rumanía, no existe una capa adicional de campos obligatorios específica de Suecia que aprender — se aplica el perfil europeo estándar.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Keine nationale CIUS über Peppol BIS hinaus', '[["Nationale Erweiterungen", "Keine über die Peppol-BIS-Billing-CIUS selbst hinaus"]]', 'Anders als Kroatiens HR-FISK oder Rumäniens RO_CIUS gibt es keine zusätzliche schwedisch-spezifische Ebene von Pflichtfeldern zu erlernen — es gilt das europäische Standardprofil.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Aucune CIUS nationale au-delà de Peppol BIS', '[["Extensions nationales", "Aucune au-delà de la CIUS Peppol BIS Billing elle-même"]]', 'Contrairement au HR-FISK de la Croatie ou au RO_CIUS de la Roumanie, il n''existe pas de couche supplémentaire de champs obligatoires propre à la Suède à apprendre — c''est le profil européen standard qui s''applique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Contenido estándar de la factura de IVA', '[["Requisito", "Se aplican las normas estándar suecas de contenido de la factura de IVA independientemente del formato"]]', 'Cualquiera que sea el formato que utilice, los requisitos legales de contenido subyacentes para una factura de IVA sueca válida siguen siendo los mismos — la cuestión del formato trata de la estructura, no del fondo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Standardinhalt der Umsatzsteuerrechnung', '[["Anforderung", "Die schwedischen Standardregeln für den Inhalt von Umsatzsteuerrechnungen gelten unabhängig vom Format"]]', 'Unabhängig vom verwendeten Format bleiben die zugrunde liegenden gesetzlichen Inhaltsanforderungen für eine gültige schwedische Umsatzsteuerrechnung gleich — die Formatfrage betrifft die Struktur, nicht den Inhalt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Contenu standard de la facture de TVA', '[["Exigence", "Les règles standard suédoises de contenu de facture de TVA s''appliquent quel que soit le format"]]', 'Quel que soit le format utilisé, les exigences légales de contenu sous-jacentes pour une facture de TVA suédoise valide restent les mêmes — la question du format porte sur la structure, pas sur le fond.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin plataforma central', '[["Portal gubernamental", "No existe ninguno"], ["Todo se enruta a través de", "La red Peppol"]]', 'Toda factura se mueve a través de Puntos de Acceso Peppol — no hay nada parecido al AMS de Croacia, al KSeF de Polonia, ni siquiera al ELMA de Noruega como capa de directorio gestionada por el gobierno.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Keine zentrale Plattform', '[["Regierungsportal", "Existiert nicht"], ["Alles läuft über", "Das Peppol-Netzwerk"]]', 'Jede Rechnung bewegt sich über Peppol Access Points — es gibt nichts Vergleichbares zu Kroatiens AMS, Polens KSeF oder selbst Norwegens ELMA als eigenständige, staatlich betriebene Verzeichnisebene.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Aucune plateforme centrale', '[["Portail gouvernemental", "N''existe pas"], ["Tout transite via", "Le réseau Peppol"]]', 'Chaque facture transite par des Access Points Peppol — il n''existe rien de comparable à l''AMS croate, au KSeF polonais, ni même à l''ELMA norvégien en tant que couche d''annuaire distincte gérée par l''État.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Gobernanza', '[["DIGG", "Autoridad Peppol de Suecia (actualmente en proceso de fusión con la PTS)"], ["SFTI", "Organismo de normalización — Single Face to Industry — no es una plataforma de transmisión"], ["Skatteverket", "Agencia Tributaria; copatrocinadora de la evaluación del mandato B2B"]]', 'La fusión en curso de DIGG con la Autoridad de Correos y Telecomunicaciones (PTS) podría cambiar el punto de contacto habitual para asuntos de la Autoridad Peppol — esté atento a orientaciones actualizadas durante la transición.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Governance', '[["DIGG", "Schwedische Peppol-Behörde (wird derzeit in die PTS eingegliedert)"], ["SFTI", "Normungsgremium — Single Face to Industry — keine Übermittlungsplattform"], ["Skatteverket", "Steuerbehörde; Mitträgerin der B2B-Pflichtbewertung"]]', 'Die laufende Fusion von DIGG mit der Post- und Telekombehörde (PTS) könnte die alltägliche Kontaktstelle für Peppol-Behördenangelegenheiten verschieben — achten Sie während des Übergangs auf aktualisierte Hinweise.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Gouvernance', '[["DIGG", "Autorité Peppol suédoise (actuellement en cours de fusion avec la PTS)"], ["SFTI", "Organisme de normalisation — Single Face to Industry — pas une plateforme de transmission"], ["Skatteverket", "Agence fiscale ; co-commanditaire de l''évaluation de l''obligation B2B"]]', 'La fusion en cours de DIGG avec l''autorité des postes et télécommunications (PTS) pourrait déplacer le point de contact habituel pour les questions relevant de l''autorité Peppol — surveillez les directives mises à jour pendant la transition.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Encontrar un socio comercial', '[["Herramienta", "Directorio en línea de Peppol"], ["Qué muestra", "Estado de conexión, formatos aceptados, identificadores comerciales (GLN o número de IVA)"]]', 'Utilice el directorio para comprobar si una contraparte sueca concreta está conectada a Peppol y qué formatos/identificadores acepta antes de construir una integración basada en suposiciones.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Einen Handelspartner finden', '[["Werkzeug", "Peppol Online Directory"], ["Was es zeigt", "Verbindungsstatus, akzeptierte Formate, Geschäftskennungen (GLN oder USt-ID)"]]', 'Nutzen Sie das Verzeichnis, um zu prüfen, ob ein bestimmter schwedischer Geschäftspartner mit Peppol verbunden ist und welche Formate/Kennungen er akzeptiert, bevor Sie eine Integration auf Basis von Annahmen aufbauen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Trouver un partenaire commercial', '[["Outil", "Annuaire en ligne Peppol"], ["Ce qu''il affiche", "Statut de connexion, formats acceptés, identifiants professionnels (GLN ou numéro de TVA)"]]', 'Utilisez l''annuaire pour vérifier si une contrepartie suédoise donnée est connectée à Peppol et quels formats/identifiants elle accepte avant de construire une intégration basée sur des hypothèses.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'El B2B hoy: voluntario pero habitual', '[["Requisito legal", "Ninguno"], ["Realidad práctica", "Alta adopción, cada vez más esperada por los grandes compradores"]]', 'Nada impide hoy que dos empresas suecas intercambien facturas electrónicas estructuradas de mutuo acuerdo — muchas ya lo hacen, muy por delante de cualquier obligación legal de hacerlo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'B2B heute: freiwillig, aber verbreitet', '[["Gesetzliche Anforderung", "Keine"], ["Praktische Realität", "Hohe Akzeptanz, von größeren Käufern zunehmend erwartet"]]', 'Nichts hindert zwei schwedische Unternehmen heute daran, strukturierte E-Rechnungen im gegenseitigen Einvernehmen auszutauschen — viele tun dies bereits, weit vor jeder rechtlichen Verpflichtung dazu.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Le B2B aujourd''hui : volontaire mais courant', '[["Exigence légale", "Aucune"], ["Réalité pratique", "Adoption élevée, de plus en plus attendue par les grands acheteurs"]]', 'Rien n''empêche aujourd''hui deux entreprises suédoises d''échanger des factures électroniques structurées d''un commun accord — beaucoup le font déjà, bien avant toute obligation légale de le faire.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔮 Lo que la investigación realmente está evaluando', NULL, NULL, 'Más allá de la pregunta binaria "mandato o no", el comisionado está examinando específicamente si Skatteverket podría usar los datos de facturación electrónica para la administración del IVA y la prevención del fraude — un indicio de que cualquier mandato eventual podría incluir un componente de reporte, no solo un requisito de formato.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔮 Was die Untersuchung tatsächlich prüft', NULL, NULL, 'Über die binäre Frage "Pflicht oder nicht" hinaus untersucht der Kommissar speziell, ob Skatteverket E-Rechnungsdaten für die Umsatzsteuerverwaltung und Betrugsbekämpfung nutzen könnte — ein Hinweis darauf, dass eine etwaige künftige Pflicht auch eine Meldekomponente umfassen könnte, nicht nur eine Formatanforderung.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔮 Ce que l''enquête évalue réellement', NULL, NULL, 'Au-delà de la question binaire « obligation ou non », le commissaire examine spécifiquement si Skatteverket pourrait utiliser les données de facturation électronique pour l''administration de la TVA et la prévention de la fraude — un indice qu''une éventuelle future obligation pourrait comporter un volet déclaratif, pas seulement une exigence de format.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🏛️ La fusión de DIGG con la PTS', NULL, NULL, 'Esté atento a cómo se preserva (o reestructura) la función de Autoridad Peppol de Suecia a medida que DIGG se fusiona con la Autoridad de Correos y Telecomunicaciones — se trata de un cambio institucional que vale la pena seguir por separado de la cuestión política.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🏛️ Die Fusion von DIGG mit der PTS', NULL, NULL, 'Achten Sie darauf, wie die Funktion der schwedischen Peppol-Behörde erhalten (oder umstrukturiert) wird, während DIGG mit der Post- und Telekombehörde fusioniert — dies ist ein institutioneller Wandel, den es getrennt von der politischen Frage zu verfolgen lohnt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🏛️ La fusion de DIGG avec la PTS', NULL, NULL, 'Surveillez la manière dont la fonction d''autorité Peppol de la Suède est préservée (ou restructurée) alors que DIGG fusionne avec l''autorité des postes et télécommunications — un changement institutionnel qui mérite d''être suivi indépendamment de la question politique.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🇪🇺 El único plazo firme: el propio ViDA', NULL, NULL, 'Independientemente de lo que concluya la investigación nacional, Suecia sigue enfrentándose al requisito transfronterizo del ViDA a nivel de la UE a partir del 1 de julio de 2030 — las empresas suecas que comercian de forma transfronteriza deben prepararse para esa fecha con independencia de la cuestión nacional.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🇪🇺 Die einzige feste Frist: ViDA selbst', NULL, NULL, 'Unabhängig davon, zu welchem Ergebnis die nationale Untersuchung kommt, steht Schweden weiterhin vor der EU-weiten grenzüberschreitenden ViDA-Anforderung ab dem 1. Juli 2030 — grenzüberschreitend handelnde schwedische Unternehmen sollten sich unabhängig von der inländischen Frage auf dieses Datum vorbereiten.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🇪🇺 La seule échéance ferme : ViDA lui-même', NULL, NULL, 'Quelles que soient les conclusions de l''enquête nationale, la Suède reste confrontée à l''exigence transfrontalière ViDA à l''échelle de l''UE à partir du 1er juillet 2030 — les entreprises suédoises pratiquant le commerce transfrontalier devraient se préparer à cette date indépendamment de la question nationale.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📈 Alta adopción voluntaria como cobertura', NULL, NULL, 'Dado que la adopción de Peppol/Svefaktura en B2B ya está muy extendida, un futuro mandato — si se legisla — probablemente formalizaría la práctica existente para muchas empresas en lugar de forzar una construcción desde cero, de forma similar a como el mandato de 2027 de Noruega hace en gran medida hoy.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📈 Hohe freiwillige Nutzung als Absicherung', NULL, NULL, 'Da die B2B-Peppol-/Svefaktura-Nutzung bereits weit verbreitet ist, würde eine künftige Pflicht — falls gesetzlich verankert — für viele Unternehmen wahrscheinlich bestehende Praxis formalisieren, statt einen Neuaufbau von Grund auf zu erzwingen, ähnlich wie es Norwegens Pflicht ab 2027 heute größtenteils tut.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📈 Une adoption volontaire élevée comme couverture', NULL, NULL, 'L''adoption de Peppol/Svefaktura en B2B étant déjà très répandue, une future obligation — si elle était légiférée — formaliserait probablement la pratique existante pour de nombreuses entreprises plutôt que d''imposer une reconstruction depuis zéro, à l''image de ce que fait déjà largement l''obligation norvégienne de 2027.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Sweden' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si abastece a organismos públicos suecos, confirme la capacidad de Peppol BIS Billing 3.0', 'Conéctese a través de un Punto de Acceso certificado o un proveedor de servicios de facturación electrónica aprobado — esto sigue siendo firmemente obligatorio para el sector público.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie schwedische öffentliche Stellen beliefern, bestätigen Sie die Peppol-BIS-Billing-3.0-Fähigkeit', 'Verbinden Sie sich über einen zertifizierten Access Point oder einen zugelassenen E-Rechnungs-Dienstanbieter — dies bleibt für den öffentlichen Sektor fest verpflichtend.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous fournissez des organismes publics suédois, confirmez votre capacité Peppol BIS Billing 3.0', 'Connectez-vous via un Access Point certifié ou un prestataire de services de facturation électronique agréé — cela reste fermement obligatoire pour le secteur public.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Consulte el Directorio en línea de Peppol antes de construir integraciones', 'Confirme el estado de conexión de su contraparte sueca y qué formatos/identificadores acepta — no dé por sentado Peppol BIS 3.0 de forma universal, dada la persistencia de formatos heredados.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie das Peppol Online Directory, bevor Sie Integrationen aufbauen', 'Bestätigen Sie den Verbindungsstatus Ihres schwedischen Geschäftspartners und welche Formate/Kennungen er akzeptiert — gehen Sie angesichts fortbestehender veralteter Formate nicht universell von Peppol BIS 3.0 aus.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Consultez l''annuaire en ligne Peppol avant de construire des intégrations', 'Confirmez le statut de connexion de votre contrepartie suédoise et quels formats/identifiants elle accepte — ne présumez pas de Peppol BIS 3.0 de manière universelle, compte tenu de la persistance des formats hérités.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Migre fuera de Svefaktura y SFTI ESAP 6 cuando sea posible', 'Estos formatos se están desaconsejando activamente, aunque técnicamente aún se aceptan — migrar a Peppol BIS 3.0 ahora evita prisas más adelante.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wechseln Sie, wo praktikabel, von Svefaktura und SFTI ESAP 6 weg', 'Diese Formate werden aktiv zurückgedrängt, obwohl sie technisch noch akzeptiert werden — ein jetziger Wechsel zu Peppol BIS 3.0 vermeidet späteren Zeitdruck.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Migrez depuis Svefaktura et SFTI ESAP 6 lorsque cela est possible', 'Ces formats sont activement déconseillés, même s''ils restent techniquement acceptés — migrer dès maintenant vers Peppol BIS 3.0 évite une précipitation plus tard.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Para el B2B, no hay nada que registrar — simplemente siga la investigación', 'Siga la investigación nacional sobre la implementación del ViDA, prevista para el 30 de noviembre de 2027, ya que sus conclusiones determinarán si surge un mandato nacional y cómo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Für B2B gibt es nichts zu registrieren — verfolgen Sie einfach die Untersuchung', 'Verfolgen Sie die nationale Untersuchung zur ViDA-Umsetzung, die bis zum 30. November 2027 fällig ist, da ihre Ergebnisse bestimmen werden, ob und wie eine inländische Pflicht entsteht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Pour le B2B, il n''y a rien à enregistrer — suivez simplement l''enquête', 'Suivez l''enquête nationale sur la mise en œuvre de ViDA, attendue pour le 30 novembre 2027, car ses conclusions détermineront si et comment une obligation nationale voit le jour.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Establezca un archivo estándar de 7 años', 'Asegúrese de que sus registros de facturas electrónicas cumplen el período de conservación, independientemente del formato que esté utilizando.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine standardmäßige 7-jährige Archivierung ein', 'Stellen Sie sicher, dass Ihre E-Rechnungsunterlagen die Aufbewahrungsfrist erfüllen, unabhängig davon, welches Format Sie verwenden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage standard de 7 ans', 'Veillez à ce que vos registres de factures électroniques respectent la durée de conservation, quel que soit le format que vous utilisez.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Sweden' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'DIGG — Autoridad Peppol de Suecia' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Sweden' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'DIGG — Schwedische Peppol-Behörde' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Sweden' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'DIGG — Autorité Peppol suédoise' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Sweden' AND dp.sort_order = 0;
